export function homeView(course,state,material,esc){const started=hasStarted(course,state);const substitutions={SECTIONS:course.catalog.sections.length,MODULES:course.modules.length,LESSONS:course.lessons.length,PRACTICE:course.lessons.reduce((n,l)=>n+l.practice.length,0),LAST:esc(material.title),START:started?"Продолжить обучение":"Начать обучение",LAST_CLASS:started?"":"home-hidden",RECOMMENDATION:state.balance==='practice'?'<button data-go="practice">К самостоятельной практике</button>':''};return `<div class="edition-home">${markup.replace(/__([A-Z_]+)__/g,(_,k)=>substitutions[k])}</div>`;}
